"""Graph algorithms: traversal, shortest paths, components, ordering, PageRank, centrality.

Every function is deterministic (sorted iteration), reports unreachable nodes explicitly rather than
inventing a distance, and raises a typed error with evidence when the input makes the answer
undefined -- a negative edge for Dijkstra, a negative cycle for Bellman-Ford, a cycle for a
topological sort.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

from .errors import CycleError, NegativeCycleError, NegativeWeightError, ValidationError
from .graph import Graph

INFINITY = math.inf


def _check_source(graph: Graph, source: str) -> None:
    if source not in graph.nodes():
        raise ValidationError(f"unknown source: {source}", known=graph.nodes()[:10])


def bfs(graph: Graph, source: str) -> dict[str, int]:
    """Hop distances from `source`; unreachable nodes are absent (never faked as -1)."""
    _check_source(graph, source)
    seen = {source: 0}
    queue = [source]
    head = 0
    while head < len(queue):
        node = queue[head]
        head += 1
        for neighbour, _ in graph.neighbors(node):
            if neighbour not in seen:
                seen[neighbour] = seen[node] + 1
                queue.append(neighbour)
    return seen


def dfs(graph: Graph, source: str) -> list[str]:
    """Pre-order depth-first walk, neighbours visited in sorted order."""
    _check_source(graph, source)
    visited: list[str] = []
    seen: set[str] = set()
    stack = [source]
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        visited.append(node)
        stack.extend(neighbour for neighbour, _ in reversed(graph.neighbors(node)) if neighbour not in seen)
    return visited


def dijkstra(graph: Graph, source: str) -> tuple[dict[str, float], dict[str, str | None]]:
    """Non-negative shortest paths; a negative edge is refused, not silently mis-answered.

    The check walks every edge once, up front: discovering a negative weight halfway through the
    relaxation loop would mean returning a distance that is simply wrong.
    """
    _check_source(graph, source)
    for edge in graph.edges():
        if edge.weight < 0:
            raise NegativeWeightError(
                "dijkstra requires non-negative weights; use bellman_ford",
                edge=f"{edge.source}->{edge.target}",
                weight=edge.weight,
            )
    distance: dict[str, float] = {source: 0.0}
    previous: dict[str, str | None] = {source: None}
    remaining = set(graph.nodes())
    while remaining:
        current = None
        best = INFINITY
        for node in sorted(remaining):
            if node in distance and distance[node] < best:
                current, best = node, distance[node]
        if current is None:
            break
        remaining.discard(current)
        for neighbour, weight in graph.neighbors(current):
            candidate = distance[current] + weight
            if neighbour not in distance or candidate < distance[neighbour]:
                distance[neighbour] = candidate
                previous[neighbour] = current
    return distance, previous


def bellman_ford(graph: Graph, source: str) -> tuple[dict[str, float], dict[str, str | None]]:
    """Shortest paths with negative weights; reports the offending cycle when one exists."""
    _check_source(graph, source)
    distance: dict[str, float] = {source: 0.0}
    previous: dict[str, str | None] = {source: None}
    nodes = graph.nodes()
    for _ in range(len(nodes) - 1):
        changed = False
        for node in nodes:
            if node not in distance:
                continue
            for neighbour, weight in graph.neighbors(node):
                candidate = distance[node] + weight
                if neighbour not in distance or candidate < distance[neighbour]:
                    distance[neighbour] = candidate
                    previous[neighbour] = node
                    changed = True
        if not changed:
            break
    for node in nodes:
        if node not in distance:
            continue
        for neighbour, weight in graph.neighbors(node):
            if neighbour not in distance or distance[node] + weight < distance[neighbour]:
                raise NegativeCycleError("negative cycle reachable from the source", at=f"{node}->{neighbour}")
    return distance, previous


def path_from(previous: dict[str, str | None], target: str) -> list[str]:
    """Reconstruct a path from a predecessor map; raises when the target is unreachable."""
    if target not in previous:
        raise ValidationError(f"unreachable target: {target}")
    path = [target]
    while previous[path[-1]] is not None:
        path.append(str(previous[path[-1]]))
    return list(reversed(path))


def components(graph: Graph) -> list[list[str]]:
    """Weakly connected components, each sorted, the list ordered by its smallest node."""
    undirected = graph if not graph.directed else _as_undirected(graph)
    seen: set[str] = set()
    groups: list[list[str]] = []
    for node in undirected.nodes():
        if node in seen:
            continue
        group = sorted(bfs(undirected, node))
        seen.update(group)
        groups.append(group)
    return groups


def _as_undirected(graph: Graph) -> Graph:
    mirror = Graph(directed=False)
    for edge in graph.edges():
        mirror.add_edge(edge.source, edge.target, edge.weight)
    return mirror


def topological_sort(graph: Graph) -> list[str]:
    """Kahn's algorithm; a cycle is reported with the nodes that could never be released."""
    if not graph.directed:
        raise ValidationError("topological sort requires a directed graph")
    in_degree = {node: 0 for node in graph.nodes()}
    for node in graph.nodes():
        for neighbour, _ in graph.neighbors(node):
            in_degree[neighbour] += 1
    ready = sorted(node for node, degree in in_degree.items() if degree == 0)
    order: list[str] = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for neighbour, _ in graph.neighbors(node):
            in_degree[neighbour] -= 1
            if in_degree[neighbour] == 0:
                ready.append(neighbour)
                ready.sort()
    if len(order) != graph.node_count:
        stuck = sorted(node for node, degree in in_degree.items() if degree > 0)
        raise CycleError("directed cycle prevents a topological order", cycle=stuck)
    return order


@dataclass(frozen=True, slots=True)
class PageRankResult:
    scores: dict[str, float]
    iterations: int
    converged: bool

    def to_document(self) -> dict[str, object]:
        return {"iterations": self.iterations, "converged": self.converged, "scores": {node: round(value, 10) for node, value in sorted(self.scores.items())}}


def pagerank(graph: Graph, *, damping: float = 0.85, tolerance: float = 1e-9, max_iterations: int = 200) -> PageRankResult:
    """Power iteration with explicit convergence reporting (never a silent iteration cap)."""
    if not 0.0 < damping < 1.0:
        raise ValidationError("damping must be in (0, 1)", value=damping)
    nodes = graph.nodes()
    if not nodes:
        return PageRankResult({}, 0, True)
    total = len(nodes)
    scores = {node: 1.0 / total for node in nodes}
    outgoing = {node: sum(weight for _, weight in graph.neighbors(node)) for node in nodes}
    # Incoming edges are collected once, outside the iteration loop: rebuilding the neighbour mapping
    # inside it was both quadratic and wasteful (the first version of this function did exactly that).
    incoming_edges: dict[str, list[tuple[str, float]]] = {node: [] for node in nodes}
    for node in nodes:
        for neighbour, weight in graph.neighbors(node):
            incoming_edges[neighbour].append((node, weight))
    converged = False
    iterations = 0
    for iterations in range(1, max_iterations + 1):
        dangling = sum(scores[node] for node in nodes if outgoing[node] == 0)
        updated: dict[str, float] = {}
        for node in nodes:
            incoming = 0.0
            for other, weight in incoming_edges[node]:
                if outgoing[other] > 0:
                    incoming += scores[other] * weight / outgoing[other]
            updated[node] = (1.0 - damping) / total + damping * (incoming + dangling / total)
        delta = sum(abs(updated[node] - scores[node]) for node in nodes)
        scores = updated
        if delta < tolerance:
            converged = True
            break
    return PageRankResult(scores, iterations, converged)


def degree_centrality(graph: Graph) -> dict[str, float]:
    """Degree normality: degree divided by the largest possible degree in an undirected reading."""
    total = graph.node_count
    if total <= 1:
        return {node: 0.0 for node in graph.nodes()}
    denominator = float(total - 1)
    return {node: round(graph.degree(node) / denominator, 10) for node in graph.nodes()}

"""Graph construction and the CSR representation.

Nodes are strings. Edges carry a numeric weight (default 1.0). Iteration order is always sorted, so
every algorithm in this package is deterministic without depending on insertion order.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from .errors import ValidationError


@dataclass(frozen=True, slots=True)
class Edge:
    source: str
    target: str
    weight: float = 1.0

    def __post_init__(self) -> None:
        if not self.source or not self.target:
            raise ValidationError("edge endpoints must be non-empty", value=f"{self.source!r}->{self.target!r}")
        if isinstance(self.weight, bool) or not isinstance(self.weight, (int, float)):
            raise ValidationError("edge weight must be a number", value=self.weight)

    def to_document(self) -> dict[str, object]:
        return {"source": self.source, "target": self.target, "weight": float(self.weight)}


@dataclass(slots=True)
class Graph:
    directed: bool = False
    _adjacency: dict[str, dict[str, float]] = field(default_factory=dict, init=False)

    # -- construction ----------------------------------------------------------------------------
    def add_node(self, node: str) -> None:
        if not node:
            raise ValidationError("node name must be non-empty")
        self._adjacency.setdefault(node, {})

    def add_edge(self, source: str, target: str, weight: float = 1.0) -> None:
        self.add_node(source)
        self.add_node(target)
        if self.directed:
            self._adjacency[source][target] = float(weight)
        else:
            self._adjacency[source][target] = float(weight)
            self._adjacency[target][source] = float(weight)

    def remove_edge(self, source: str, target: str) -> bool:
        removed = False
        if source in self._adjacency and target in self._adjacency[source]:
            del self._adjacency[source][target]
            removed = True
        if not self.directed and target in self._adjacency and source in self._adjacency[target]:
            del self._adjacency[target][source]
            removed = True
        return removed

    @classmethod
    def from_edges(cls, edges: list[Edge], *, directed: bool = False) -> "Graph":
        graph = cls(directed=directed)
        for edge in edges:
            graph.add_edge(edge.source, edge.target, edge.weight)
        return graph

    # -- queries ---------------------------------------------------------------------------------
    @property
    def node_count(self) -> int:
        return len(self._adjacency)

    def nodes(self) -> list[str]:
        return sorted(self._adjacency)

    def neighbors(self, node: str) -> list[tuple[str, float]]:
        if node not in self._adjacency:
            raise ValidationError(f"unknown node: {node}", known=self.nodes()[:10])
        return [(target, self._adjacency[node][target]) for target in sorted(self._adjacency[node])]

    def edges(self) -> list[Edge]:
        seen: set[tuple[str, str]] = set()
        result: list[Edge] = []
        for source in self.nodes():
            for target in sorted(self._adjacency[source]):
                if not self.directed and (target, source) in seen:
                    continue
                seen.add((source, target))
                result.append(Edge(source, target, self._adjacency[source][target]))
        return result

    def edge_count(self) -> int:
        return len(self.edges())

    def degree(self, node: str) -> int:
        if node not in self._adjacency:
            raise ValidationError(f"unknown node: {node}")
        return len(self._adjacency[node])

    def weighted_degree(self, node: str) -> float:
        self.neighbors(node)
        return sum(self._adjacency[node].values())

    def self_loops(self) -> list[str]:
        return [node for node in self.nodes() if node in self._adjacency[node]]

    def has_negative_weights(self) -> bool:
        return any(edge.weight < 0 for edge in self.edges())

    def csr(self) -> tuple[list[str], list[int], list[tuple[str, float]]]:
        """Compressed sparse row: node order, offsets, and the flattened neighbour list."""
        nodes = self.nodes()
        offsets = [0]
        flat: list[tuple[str, float]] = []
        for node in nodes:
            flat.extend(self.neighbors(node))
            offsets.append(len(flat))
        return nodes, offsets, flat

    def to_document(self) -> dict[str, object]:
        return {
            "directed": self.directed,
            "nodes": self.node_count,
            "edges": self.edge_count(),
            "selfLoops": self.self_loops(),
            "negativeWeights": self.has_negative_weights(),
        }

"""Incremental maintenance of weakly connected components.

Edge insertions update the labelling in near-constant time with a union-find structure. Edge
**removals** cannot be undone that way, so instead of pretending otherwise the structure marks itself
stale and says which algorithms must be recomputed -- an honest incremental API reports what it no
longer knows.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from .errors import ValidationError
from .graph import Graph


@dataclass(slots=True)
class IncrementalComponents:
    """Union-find over an undirected reading of a graph, with staleness tracking."""

    graph: Graph
    _parent: dict[str, str] = field(default_factory=dict, init=False)
    _rank: dict[str, int] = field(default_factory=dict, init=False)
    _stale: set[str] = field(default_factory=set, init=False)
    revision: int = field(default=0, init=False)

    def __post_init__(self) -> None:
        if self.graph.directed:
            raise ValidationError("incremental components follow the undirected reading; pass a directed graph through as_undirected")
        for node in self.graph.nodes():
            self._parent[node] = node
            self._rank[node] = 0
        for edge in self.graph.edges():
            self._union(edge.source, edge.target)
        self.revision = 1

    # -- union-find ------------------------------------------------------------------------------
    def _find(self, node: str) -> str:
        self._parent.setdefault(node, node)
        self._rank.setdefault(node, 0)
        while self._parent[node] != node:
            self._parent[node] = self._parent[self._parent[node]]
            node = self._parent[node]
        return node

    def _union(self, left: str, right: str) -> bool:
        root_left, root_right = self._find(left), self._find(right)
        if root_left == root_right:
            return False
        if self._rank[root_left] < self._rank[root_right]:
            root_left, root_right = root_right, root_left
        self._parent[root_right] = root_left
        if self._rank[root_left] == self._rank[root_right]:
            self._rank[root_left] += 1
        return True

    # -- maintenance -----------------------------------------------------------------------------
    def add_edge(self, source: str, target: str, weight: float = 1.0) -> bool:
        """Insert an edge; returns True when two components merged.

        Insertion never clears staleness. A removal may have split any part of the graph, and a
        single merge -- even re-adding the removed edge -- is not proof the labelling matches the
        whole graph again; only ``recompute`` can confirm that.
        """
        self.graph.add_edge(source, target, weight)
        merged = self._union(source, target)
        self.revision += 1
        return merged

    def remove_edge(self, source: str, target: str) -> bool:
        """Remove an edge. Union-find cannot split, so the labelling becomes stale for those nodes."""
        removed = self.graph.remove_edge(source, target)
        if removed:
            self.revision += 1
            self._stale.update((source, target))
        return removed

    @property
    def is_stale(self) -> bool:
        return bool(self._stale)

    def stale_nodes(self) -> list[str]:
        return sorted(self._stale)

    # -- answers ---------------------------------------------------------------------------------
    def labels(self) -> dict[str, str]:
        """Component label per node (the smallest member's name), or an error if a removal happened."""
        if self._stale:
            raise ValidationError(
                "components are stale after an edge removal; rebuild or recompute",
                stale=self.stale_nodes()[:10],
            )
        return {node: self._canonical(self._find(node)) for node in self.graph.nodes()}

    def component_count(self) -> int:
        return len(set(self.labels().values()))

    def recompute(self) -> None:
        """Full rebuild: the honest answer after a removal."""
        self._parent = {}
        self._rank = {}
        for node in self.graph.nodes():
            self._parent[node] = node
            self._rank[node] = 0
        for edge in self.graph.edges():
            self._union(edge.source, edge.target)
        self._stale.clear()
        self.revision += 1

    def _canonical(self, root: str) -> str:
        members = [node for node in self.graph.nodes() if self._find(node) == root]
        return min(members) if members else root

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"revision": self.revision, "stale": self.is_stale, "nodes": self.graph.node_count}
        if not self.is_stale:
            document["components"] = self.component_count()
        return document

"""Exception hierarchy with stable `kind` values.

The three failure modes that matter for graph work each get their own type, because each one means
"the answer you asked for does not exist" rather than "the call was malformed": a negative edge under
Dijkstra, a negative cycle under Bellman-Ford, and a cycle under topological sort.
"""

from __future__ import annotations


class GraphError(Exception):
    """Base class for every error this package raises on purpose."""

    kind = "graph_error"

    def __init__(self, message: str, **context: object) -> None:
        super().__init__(message)
        self.message = message
        self.context = {key: value for key, value in context.items() if value is not None}

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"error": self.kind, "message": self.message}
        document.update(self.context)
        return document


class ParseError(GraphError):
    """Malformed input rows or documents."""

    kind = "parse_error"

    def __init__(self, message: str, *, line: int | None = None, **context: object) -> None:
        super().__init__(message, line=line, **context)


class ValidationError(GraphError):
    """A request that is well-formed but not allowed: unknown node, undirected sort, bad damping."""

    kind = "validation_error"


class NegativeWeightError(GraphError):
    """Dijkstra was asked for shortest paths over a graph with a negative edge."""

    kind = "negative_weight_error"


class NegativeCycleError(GraphError):
    """Bellman-Ford found a negative cycle reachable from the source: no finite answer exists."""

    kind = "negative_cycle_error"


class CycleError(GraphError):
    """A topological order was requested for a graph that has a directed cycle."""

    kind = "cycle_error"


class OutputError(GraphError):
    """The output target cannot be used safely."""

    kind = "output_error"

